begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('68000000-0000-4000-8000-000000000001','release-charts@example.test','{}');
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"68000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Chart','Family','+13035550100','chart@example.test','EMAIL',null,null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Chart dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='client'),null,'Other dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
select public.save_patient_qol('69000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,now(),'Caregiver','Appetite','','Comfortable mobility','','','','Clinical QOL notes');
select public.sign_patient_qol('69000000-0000-4000-8000-000000000001',1);
select public.add_patient_qol_addendum('69000000-0000-4000-8000-000000000011','69000000-0000-4000-8000-000000000001','QOL signed addendum');
select public.save_dental_chart('69000000-0000-4000-8000-000000000002',(select id from fx where k='pet'),null,'adult',now(),'Dental clinical notes','{}');
select public.sign_dental_chart('69000000-0000-4000-8000-000000000002',(select id from fx where k='pet'),1);
select public.add_dental_addendum('69000000-0000-4000-8000-000000000012','69000000-0000-4000-8000-000000000002',(select id from fx where k='pet'),'Dental signed addendum');
select public.save_patient_anesthesia_record('69000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),null,jsonb_build_object('procedure_name','Test procedure','started_at',now()-interval '1 hour','ended_at',now(),'team','Test team','assessment','Assessment','plan','Plan','recovery_notes','Recovery','observations','[]'::jsonb,'events','[]'::jsonb,'source','manual','source_description','PRIVATE TRANSCRIPTION WORKFLOW'));
select public.sign_patient_anesthesia_record('69000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),1);
select public.add_anesthesia_record_addendum('69000000-0000-4000-8000-000000000013','69000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),'Anesthesia signed addendum');
select public.prepare_patient_document('69000000-0000-4000-8000-000000000020',(select id from fx where k='pet'),null,'PRIVATE-photo.png','image/png',10,'medical_record','',null,'internal');
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":10,"mimetype":"image/png"}'::jsonb from public.patient_documents where id='69000000-0000-4000-8000-000000000020';
select public.finalize_patient_document('69000000-0000-4000-8000-000000000020');
select public.record_lesion_observation('69000000-0000-4000-8000-000000000004','69000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),null,now(),'Mass A','left',0.2,0.4,12,10,null,'Initial observation','69000000-0000-4000-8000-000000000020');
select public.correct_lesion_observation('69000000-0000-4000-8000-000000000014','69000000-0000-4000-8000-000000000004','Measurement correction retained');
select public.save_patient_qol('69000000-0000-4000-8000-000000000006',(select id from fx where k='pet'),null,now(),'Caregiver','','','','','','','PRIVATE DRAFT');
insert into data values('selection','{"qol_ids":["69000000-0000-4000-8000-000000000001"],"dental_ids":["69000000-0000-4000-8000-000000000002"],"anesthesia_ids":["69000000-0000-4000-8000-000000000003"],"lesion_ids":["69000000-0000-4000-8000-000000000005"]}');
create function pg_temp.preview_charts(s jsonb) returns jsonb language sql as $$select public.preview_record_release((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','chart@example.test',s)$$;
create function pg_temp.confirm_charts(i uuid,p jsonb) returns public.record_releases language sql as $$select public.confirm_record_release(i,(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','chart@example.test',(select v from data where k='selection'),p->'snapshot',p->>'source_hash',true)$$;
select throws_ok($$select pg_temp.preview_charts('{"qol_ids":["69000000-0000-4000-8000-000000000006"]}')$$,'23514','Only signed QOL records from this patient can be released','QOL drafts excluded');
select throws_ok($$select public.preview_record_release((select id from fx where k='other'),(select id from fx where k='client'),'EMAIL','chart@example.test',(select v from data where k='selection'))$$,'23514',null,'Other patient signed charts excluded');
select throws_ok($$select public.preview_record_release_v1((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','chart@example.test','{}')$$,'42501',null,'Private compatibility helper not callable by staff');
insert into data select 'preview',pg_temp.preview_charts((select v from data where k='selection'));
select is((select v#>>'{snapshot,schema_version}' from data where k='preview'),'2','Extended chart snapshot is version 2');
select is((select v#>>'{snapshot,qol_records,0,addenda,0,content}' from data where k='preview'),'QOL signed addendum','All QOL addenda included');
select is((select v#>>'{snapshot,dental_charts,0,addenda,0,content}' from data where k='preview'),'Dental signed addendum','All dental addenda included');
select is((select v#>>'{snapshot,anesthesia_records,0,addenda,0,content}' from data where k='preview'),'Anesthesia signed addendum','All anesthesia addenda included');
select is((select v#>>'{snapshot,lesions,0,observations,0,corrections,0,reason}' from data where k='preview'),'Measurement correction retained','Body map includes correction history');
select is((select v#>'{snapshot,lesions,0,observations,0,photo_document_id}' from data where k='preview'),'null'::jsonb,'Unselected private body-map photo is omitted');
select ok((select v::text not like '%PRIVATE%' from data where k='preview'),'Draft and transcription workflow text excluded');
select is(jsonb_array_length(public.list_record_release_sources((select id from fx where k='pet'),0)->'qol_ids'),1,'Candidate list excludes QOL drafts');
select is(public.list_record_release_sources((select id from fx where k='pet'),0)->>'policy_accepted','false','New form acceptance starts disabled');
reset role;
insert into public.record_release_policy(id,enabled,accepted_by,accepted_at,acceptance_reference,accepted_schema_version) values(true,true,'Test reviewer',now(),'SYNTHETIC ONLY',1);
set local role authenticated;
select throws_ok($$select pg_temp.confirm_charts('69000000-0000-4000-8000-000000000007',(select v from data where k='preview'))$$,'42501',null,'Old form acceptance cannot approve extended chart form');
reset role;
update public.record_release_policy set accepted_schema_version=2;
set local role authenticated;
select public.add_patient_qol_addendum('69000000-0000-4000-8000-000000000015','69000000-0000-4000-8000-000000000001','Correction since preview');
select throws_ok($$select pg_temp.confirm_charts('69000000-0000-4000-8000-000000000007',(select v from data where k='preview'))$$,'40001',null,'New chart addendum invalidates a stale preview');
update data set v=pg_temp.preview_charts((select v from data where k='selection')) where k='preview';
select lives_ok($$select pg_temp.confirm_charts('69000000-0000-4000-8000-000000000007',(select v from data where k='preview'))$$,'Confirm extended package');
select is((select count(*) from public.record_release_sources),4::bigint,'Every extended source linked');
select is(public.read_record_release('69000000-0000-4000-8000-000000000007')->>'eligible','true','Unchanged extended package eligible');
select public.add_dental_addendum('69000000-0000-4000-8000-000000000016','69000000-0000-4000-8000-000000000002',(select id from fx where k='pet'),'Later dental correction');
select is(public.read_record_release('69000000-0000-4000-8000-000000000007')->>'eligible','false','Dental addendum invalidates package');
select public.add_anesthesia_record_addendum('69000000-0000-4000-8000-000000000017','69000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),'Later anesthesia correction');
select ok(exists(select 1 from public.record_release_events where reason like 'Reviewed anesthesia%'),'Anesthesia addendum invalidation audited');
select public.record_lesion_observation('69000000-0000-4000-8000-000000000018','69000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),1,now(),'Mass A','left',0.2,0.4,15,11,null,'Follow-up',null);
select ok(exists(select 1 from public.record_release_events where reason like 'Reviewed lesion%'),'New lesion observation invalidates package');
select public.correct_lesion_observation('69000000-0000-4000-8000-000000000021','69000000-0000-4000-8000-000000000018','Follow-up measurement correction');
select is((select count(*) from public.record_release_events where reason like 'Reviewed lesion%'),2::bigint,'Both new observation and correction invalidate lesion history');
select is((select snapshot from public.record_releases),(select v->'snapshot' from data where k='preview'),'Extended original snapshot never changes');
select lives_ok($$select pg_temp.confirm_charts('69000000-0000-4000-8000-000000000007',(select v from data where k='preview'))$$,'Exact original confirmation retry still resolves after invalidation');
-- A pre-extension v1 package must continue to validate using its original snapshot format.
insert into fx select 'soap',id from public.save_clinical_encounter(null,(select id from fx where k='pet'),null,now(),'clinic','','S','O','A','P');
select public.sign_clinical_encounter((select id from fx where k='soap'),1);
reset role;
insert into data select 'old_selection',jsonb_build_object('encounter_ids',jsonb_build_array((select id from fx where k='soap')));
insert into data select 'old_preview',public.preview_record_release_v1((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','chart@example.test',(select v from data where k='old_selection'));
insert into public.record_releases(id,pet_id,client_id,channel,recipient,selection,snapshot,source_hash,request,created_by) select '69000000-0000-4000-8000-000000000019',(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','chart@example.test',(select v from data where k='old_selection'),v->'snapshot',v->>'source_hash','{}','68000000-0000-4000-8000-000000000001' from data where k='old_preview';
set local role authenticated;
select is(public.read_record_release('69000000-0000-4000-8000-000000000019')->>'eligible','true','Existing schema-v1 package remains valid after extension');
select * from finish();
rollback;
